(** The functions, decoded as a module. *)
Definition libioread_module : module := Eval vm_compute in
  match decode_module libioread_term with Some md => md | None => [] end.

(** The term decodes to the module. *)
Lemma libioread_decodes : decode_module libioread_term = Some libioread_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition libioread_fn (n : string) : func :=
  match find_direct (TAtom n) libioread_module with
  | Some (Defined f) => f
  | _ => mkFunc (TAtom n) (TAtom "export") (RClass W) [] []
  end.

